$ R(\vartheta) = R_0(1+\alpha_{\vartheta_0}\cdot\Delta\vartheta) = R_0(1+\alpha_{\vartheta_0}\cdot(\vartheta-\vartheta_0))$

\begin{align*}
\frac{\Delta R}{R(-20\gC)} &= \frac{R(70\gC) - R(-20\gC)}{R(-20\gC)} 

&= \frac{R_0 (1+\alpha_{20\gC}(70\gC-20\gC)) - R_0 (1+\alpha_{20\gC}(-20\gC-20\gC))}{R_0 (1+\alpha_{20\gC}\cdot(-20\gC-20\gC))} 

&= \frac{\alpha_{20\gC} \cdot 50\mathrm{K} - \alpha_{20\gC}\cdot(-40\mathrm{K})}{1+\alpha_{20\gC}\cdot(-40\mathrm{K})}
= \frac{\alpha_{20\gC}(50\mathrm{K} + 40\mathrm{K})}{1 - \alpha_{20\gC} \cdot 40\mathrm{K}} 

&= \frac{-18 \cdot 10^{-3}}{1 + 8 \cdot 10^{-3}}
= \frac{-18}{1008} = -0,01786 = -1,786\,\%
\end{align*}

